import os
import subprocess
import sys
from agents import function_tool

@function_tool
def run_resume_parser_batch(folder: str, timeout_s: int=300) -> str:
    cmd = [sys.executable, '/opt/recruiting/scripts/parse_resumes.py', '--input', folder]
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s)
    except subprocess.TimeoutExpired:
        return 'parser timed out'
    out = p.stdout.strip()[-2000:]
    if p.returncode != 0:
        return f'parser failed ({p.returncode}): {p.stderr.strip()[-500:]}'
    # Remove source resumes after a successful parse
    for name in os.listdir(folder):
        path = os.path.join(folder, name)
        if os.path.isfile(path) and name.lower().endswith(('.pdf', '.docx', '.doc', '.txt')):
            os.remove(path)
    return out
